\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}

\newcommand{\Map}{\operatorname{Map}}
\newcommand{\coind}{\operatorname{coind}}
\newcommand{\id}{\mathrm{id}}
\newcommand{\Zt}{\mathbb{Z}_2}
\newcommand{\Sig}{\Sigma}

\title{The Suspension Tower of a Free $\Zt$-Complex and the Excess Spectrum of the Cross-Polytope Spheres}
\author{Aristotle}
\date{2026-07-14}

\begin{document}

\begin{abstract}
We develop a purely combinatorial theory of free $\Zt$-complexes and their equivariant (antipodal) simplicial maps, taking as models the boundary spheres $S^n$ of the $(n+1)$-dimensional cross-polytopes with the coordinate-swap involution. We assemble the suspension operation into a rigorous endofunctor of the category of antipodal maps and construct the suspension tower $\Sig^k$, the $k$-fold iterate lifting a map $S^m \to S^n$ to $S^{m+k} \to S^{n+k}$. We prove the functor laws and lift them to the tower by induction. We then establish two complementary propagation principles: a constructive one (the tower preserves coindex witnesses, so lower bounds climb undiminished) and an obstructive one (two descent lemmas, obtained by composing with the equatorial inclusion, spread a single non-existence fact across an entire cone of dimensions). Combining descent with three finite Borsuk--Ulam base instances---the non-existence of antipodal maps $S^1 \to S^0$, $S^2 \to S^1$, and $S^3 \to S^2$---yields the non-existence of antipodal maps $S^{m+1} \to S^0$, $S^{m+2} \to S^1$, and $S^{m+3} \to S^2$ for all $m$. Together with the diagonal lower bound this pins $\coind(S^n) = n$ for $n \in \{0,1,2\}$, showing that the bottom three rungs of the suspension tower each raise the coindex by precisely one unit.
\end{abstract}

\maketitle

\section{Introduction}

The Borsuk--Ulam theorem asserts that every continuous map $S^n \to \mathbb{R}^n$ identifies a pair of antipodal points, or equivalently that there is no continuous antipodal (odd) map $S^n \to S^{n-1}$. In equivariant language it says that the $\Zt$-coindex of $S^n$---the largest $d$ with an equivariant map $S^d \to S^n$---equals $n$. The coindex is a central lower-bound invariant in topological combinatorics.

We isolate a finite, combinatorial core of these ideas and organize it around the \emph{suspension tower}. We work in the category whose objects are the cross-polytope boundary spheres with their antipodal involution and whose morphisms are equivariant simplicial maps. The contributions are: (1) suspension is an endofunctor, with an iterated tower and lifted functor laws (\S4); (2) a constructive propagation theorem---the tower preserves coindex witnesses (\S5); (3) two descent principles turning one non-existence statement into a cone (\S6); (4) a determination of the excess spectrum at the base, giving $\coind(S^n) = n$ for $n \le 2$ (\S7).

\section{The combinatorial model}

\subsection{Cross-polytope spheres}
For $n \ge 0$, the $(n+1)$-dimensional cross-polytope is the convex hull of $\{\pm e_0, \dots, \pm e_n\}$ in $\mathbb{R}^{n+1}$; we model $S^n$ by its boundary complex.

\begin{definition}[vertices]
The vertex set of $S^n$ is $V(S^n) = \{(i,b) : i \in \{0,\dots,n\},\ b \in \{0,1\}\}$, so $|V(S^n)| = 2(n+1)$. We read $(i,0)$ as $+e_i$ and $(i,1)$ as $-e_i$; $i$ is the \emph{axis} and $b$ the \emph{sign}.
\end{definition}

\begin{definition}[antipodal involution]
The free involution is $a(i,b) = (i, 1-b)$; it has no fixed points, so the $\Zt$-action is free.
\end{definition}

\begin{definition}[simplices]
A subset $\sigma \subseteq V(S^n)$ is a simplex iff it contains at most one vertex from each antipodal pair. The facets are the sign-selections $\{(i,s_i) : i = 0,\dots,n\}$ for $s \in \{0,1\}^{n+1}$; there are $2^{n+1}$, each of dimension $n$.
\end{definition}

This is the antipodal join $S^0 * \cdots * S^0$ of $n+1$ copies of $S^0$.

\subsection{Antipodal maps}

\begin{definition}[antipodal map]
An antipodal map $F : S^m \to S^n$ is a vertex map $f : V(S^m) \to V(S^n)$ that is \emph{equivariant} ($f(a(v)) = a(f(v))$) and \emph{simplicial} ($f(\sigma)$ is a simplex whenever $\sigma$ is). Write $\Map(S^m,S^n)$ for the set of such maps.
\end{definition}

\begin{lemma}[Extensionality]
Two antipodal maps $S^m \to S^n$ are equal iff their vertex maps agree.
\end{lemma}
\begin{proof}[Proof sketch]
Equivariance and simpliciality are proof-irrelevant properties of the vertex map; records with equal vertex maps are equal.
\end{proof}

For each $n$ the identity vertex map yields $\id_{S^n}$, and vertex-wise composition of antipodal maps is antipodal, so the cross-polytope spheres and antipodal maps form a category.

\subsection{The coindex}

\begin{definition}[coindex]
$\coind(S^n) = \max\{d : \Map(S^d,S^n) \ne \varnothing\}$.
\end{definition}

Whenever $m \le n$ there is an antipodal map $S^m \to S^n$ (axis-preserving inclusion); we call this the \emph{diagonal lower bound}, and $\id_{S^n}$ gives $\coind(S^n) \ge n$. The \emph{equatorial inclusion} $\iota_n : S^n \hookrightarrow S^{n+1}$ embeds the first $n+1$ axes, omitting the polar axis.

\section{Structural characterization}

\begin{proposition}[existence criterion]
An antipodal map $F : S^m \to S^n$ is determined by $g(i) := f(i,0)$, since $f(i,1) = a(g(i))$. Simpliciality holds iff the axes of $g(0),\dots,g(m)$ are pairwise distinct; hence $\Map(S^m,S^n) \ne \varnothing$ iff $m \le n$.
\end{proposition}
\begin{proof}[Proof sketch]
For distinct axes $i \ne j$ write $g(i) = (a_i,c_i)$, $g(j) = (a_j,c_j)$. A facet with signs $s_i,s_j$ maps $(i,s_i),(j,s_j)$ to $(a_i,c_i \oplus s_i),(a_j,c_j \oplus s_j)$. If $a_i = a_j$ one can choose signs making these antipodal, so simpliciality forces $a_i \ne a_j$; conversely distinct axes suffice. Injectivity of $m+1$ axes into $n+1$ requires $m \le n$.
\end{proof}

The sections below rebuild both directions functorially, proving the impossibility direction only up to base rungs verifiable by exhaustive search and extending them by the machinery.

\section{Suspension as an endofunctor}

\begin{definition}[suspension]
The suspension of $F : S^m \to S^n$ is $\Sig F : S^{m+1} \to S^{n+1}$: on equatorial axes $i \le m$ it acts as $F$ (into the first $n+1$ axes), and on the new polar axis $m+1$ it sends $(m+1,b) \mapsto (n+1,b)$. Geometrically $\Sig F = F * \id_{S^0}$.
\end{definition}

\begin{theorem}[functoriality]
$\Sig(\id_{S^n}) = \id_{S^{n+1}}$ and $\Sig(G \circ F) = \Sig G \circ \Sig F$.
\end{theorem}
\begin{proof}[Proof sketch]
By Extensionality check vertex maps; by the case split check separately on the polar and equatorial vertices, where both sides reduce to the identity resp.\ the underlying (composite) map.
\end{proof}

\begin{definition}[suspension tower]
$\Sig^0 F = F$ and $\Sig^{k+1} F = \Sig(\Sig^k F)$, so $\Sig^k F : S^{m+k} \to S^{n+k}$.
\end{definition}

\begin{theorem}[functor laws for the tower]
For every $k$: $\Sig^k(\id_{S^n}) = \id_{S^{n+k}}$ and $\Sig^k(G \circ F) = \Sig^k G \circ \Sig^k F$.
\end{theorem}
\begin{proof}[Proof sketch]
Induction on $k$, applying the single-step laws to the height-$k$ instance.
\end{proof}

\section{Constructive propagation}

\begin{theorem}[lifting]
If $\Map(S^m,S^n) \ne \varnothing$ then $\Map(S^{m+k},S^{n+k}) \ne \varnothing$ for every $k$.
\end{theorem}
\begin{proof}
Apply $\Sig^k$ to a witness.
\end{proof}

\begin{corollary}[diagonal bound is tower-stable]
If $m \le n$ then $\Map(S^{m+k},S^{n+k}) \ne \varnothing$ for every $k$.
\end{corollary}

\begin{corollary}[base-point tower]
For all $n,k$ there is an antipodal map $S^k \to S^{n+k}$.
\end{corollary}
\begin{proof}
Suspend the equatorial map $S^0 \to S^n$ $k$ times.
\end{proof}

\section{Obstructive propagation: descent}

\begin{theorem}[codomain descent]
If $\Map(S^m,S^{n+1}) = \varnothing$ then $\Map(S^m,S^n) = \varnothing$.
\end{theorem}
\begin{proof}
$F : S^m \to S^n$ would give $\iota_n \circ F : S^m \to S^{n+1}$.
\end{proof}

\begin{theorem}[domain ascent]
If $\Map(S^m,S^n) = \varnothing$ then $\Map(S^{m+1},S^n) = \varnothing$.
\end{theorem}
\begin{proof}
$F : S^{m+1} \to S^n$ would give $F \circ \iota_m : S^m \to S^n$.
\end{proof}

\section{The excess spectrum at the base}

\begin{lemma}[finite base instances]
$\Map(S^1,S^0) = \varnothing$, $\Map(S^2,S^1) = \varnothing$, and $\Map(S^3,S^2) = \varnothing$.
\end{lemma}
\begin{proof}[Proof sketch]
By the existence criterion an antipodal map $S^{n+1} \to S^n$ would require injecting $n+2$ axes into $n+1$; for $n = 0,1,2$ one enumerates the finitely many positive-vertex assignments and finds an antipodal image pair in some facet for each.
\end{proof}

\begin{theorem}[non-existence to low spheres]
For every $m \ge 0$: $\Map(S^{m+1},S^0) = \varnothing$, $\Map(S^{m+2},S^1) = \varnothing$, and $\Map(S^{m+3},S^2) = \varnothing$.
\end{theorem}
\begin{proof}
Induction on $m$ with base cases the previous lemma and step domain ascent.
\end{proof}

\begin{theorem}[sharp diagonal]
For $n \in \{0,1,2\}$ there is no antipodal map $S^{n+1} \to S^n$.
\end{theorem}

\begin{theorem}[excess spectrum at the base]
For $n \in \{0,1,2\}$, $\Map(S^n,S^n) \ne \varnothing$ and $\Map(S^{n+1},S^n) = \varnothing$; hence $\coind(S^n) = n$ exactly.
\end{theorem}
\begin{proof}
$\id_{S^n}$ gives the first clause and the sharp diagonal the second.
\end{proof}

Climbing one rung of the suspension tower thus raises the coindex by precisely one at each of the bottom three levels: the constructive half forces the increment to be at least one, the obstructive half at most one.

\section{Applications and future work}

The coindex is a workhorse lower-bound invariant, underlying Ham-Sandwich--type partition theorems, necklace-splitting/fair-division results, and Kneser-type chromatic bounds. The framework's distinctive feature is modularity: a few exhaustively checked base cases, amplified by descent and lifting, produce infinite families of obstructions with functorial coherence. Future work includes uniformizing the obstruction to all $n$ via the axis pigeonhole of the existence criterion, extending the tower to general free $\Zt$-complexes, and studying its interaction with joins and box/Hom-complexes.

\end{document}

