"""Demo: exhaustive decision of antipodal maps between cross-polytope spheres.

Confirms the existence criterion  Map(S^m, S^n) != {}  <=>  m <= n  by brute force,
and prints the resulting existence table.
"""
from __future__ import annotations
from itertools import product
from typing import Iterator

Vertex = tuple[int, int]
Map = tuple[Vertex, ...]

def antipode(v: Vertex) -> Vertex:
    i, b = v
    return (i, 1 - b)

def facets(n: int) -> Iterator[tuple[Vertex, ...]]:
    for signs in product((0, 1), repeat=n + 1):
        yield tuple((i, signs[i]) for i in range(n + 1))

def is_simplex(sigma) -> bool:
    seen: dict[int, int] = {}
    for (i, b) in sigma:
        if i in seen and seen[i] != b:
            return False
        seen[i] = b
    return True

def apply_map(g: Map, v: Vertex) -> Vertex:
    i, b = v
    return g[i] if b == 0 else antipode(g[i])

def exists_map(m: int, n: int) -> bool:
    verts = [(i, b) for i in range(n + 1) for b in (0, 1)]
    for g in product(verts, repeat=m + 1):
        if all(is_simplex(apply_map(g, v) for v in f) for f in facets(m)):
            return True
    return False

def main() -> None:
    N = 4
    print("existence table (+ = antipodal map exists):")
    for m in range(N + 1):
        row = "".join(" + " if exists_map(m, n) else " . " for n in range(N + 1))
        print(f"m={m}: {row}")
        for n in range(N + 1):
            assert exists_map(m, n) == (m <= n)
    print("criterion verified: Map(S^m,S^n) nonempty iff m <= n")

if __name__ == "__main__":
    main()

"""Demo: computing the Z2-coindex of small cross-polytope spheres.

coind(S^n) = max d such that an antipodal map S^d -> S^n exists.  The output confirms
coind(S^n) = n for n = 0..3, the Borsuk-Ulam value.
"""
from __future__ import annotations
from itertools import product

Vertex = tuple[int, int]

def antipode(v: Vertex) -> Vertex:
    return (v[0], 1 - v[1])

def is_simplex(sigma) -> bool:
    seen: dict[int, int] = {}
    for (i, b) in sigma:
        if i in seen and seen[i] != b:
            return False
        seen[i] = b
    return True

def exists_map(m: int, n: int) -> bool:
    verts = [(i, b) for i in range(n + 1) for b in (0, 1)]
    facets = [tuple((i, s[i]) for i in range(m + 1)) for s in product((0, 1), repeat=m + 1)]
    for g in product(verts, repeat=m + 1):
        ok = True
        for f in facets:
            img = [g[i] if b == 0 else antipode(g[i]) for (i, b) in f]
            if not is_simplex(img):
                ok = False
                break
        if ok:
            return True
    return False

def coindex(n: int) -> int:
    best = -1
    for d in range(n + 3):
        if exists_map(d, n):
            best = d
    return best

def main() -> None:
    for n in range(4):
        c = coindex(n)
        print(f"coind(S^{n}) = {c}")
        assert c == n
    print("coind(S^n) = n confirmed (Borsuk-Ulam).")

if __name__ == "__main__":
    main()

"""Demo: the suspension tower lifts a low-dimensional antipodal map to any height,
and verifies functoriality  susp(G o F) = susp(G) o susp(F).
"""
from __future__ import annotations
from itertools import product

Vertex = tuple[int, int]
Map = tuple[Vertex, ...]

def antipode(v: Vertex) -> Vertex:
    return (v[0], 1 - v[1])

def apply_map(g: Map, v: Vertex) -> Vertex:
    i, b = v
    return g[i] if b == 0 else antipode(g[i])

def is_simplex(sigma) -> bool:
    seen: dict[int, int] = {}
    for (i, b) in sigma:
        if i in seen and seen[i] != b:
            return False
        seen[i] = b
    return True

def is_antipodal_map(g: Map, m: int, n: int) -> bool:
    for s in product((0, 1), repeat=m + 1):
        img = [apply_map(g, (i, s[i])) for i in range(m + 1)]
        if not is_simplex(img):
            return False
    return True

def compose(g2: Map, g1: Map) -> Map:
    return tuple(apply_map(g2, g1[i]) for i in range(len(g1)))

def suspend(g: Map, n: int) -> Map:
    return tuple(list(g) + [(n + 1, 0)])

def main() -> None:
    # tower over the equatorial map S^0 -> S^1
    F: Map = ((0, 0),)
    n = 1
    cur = F
    cn = n
    for k in range(1, 5):
        cur = suspend(cur, cn)
        cn += 1
        assert is_antipodal_map(cur, k, cn)
        print(f"susp^{k}(F): S^{k} -> S^{cn}  valid={cur}")
    # functoriality
    F12: Map = ((0, 0), (1, 0))          # S^1 -> S^2
    G23: Map = ((0, 0), (1, 0), (2, 0))  # S^2 -> S^3
    lhs = suspend(compose(G23, F12), 3)
    rhs = compose(suspend(G23, 3), suspend(F12, 2))
    assert lhs == rhs
    print("functoriality susp(G o F) = susp(G) o susp(F):", lhs == rhs)

if __name__ == "__main__":
    main()

