function DECIDE-ANTIPODAL-MAP(m, n):
  V <- all vertices (i,b) of S^n
  F <- all facets of S^m (one signed vertex per axis)
  for each g in V^{m+1}:            # image of each positive vertex (i,0)
    ok <- true
    for each facet phi in F:
      image <- [ g[i] if b=0 else antipode(g[i]) for (i,b) in phi ]
      if image contains an antipodal pair: ok <- false; break
    if ok: return g               # witness found
  return NONE                       # Map(S^m,S^n) is empty

