from __future__ import annotations
from typing import Optional

Vertex = tuple[int, int]
Map = tuple[Vertex, ...]

def antipode(v: Vertex) -> Vertex:
    return (v[0], 1 - v[1])

def apply_map(g: Map, v: Vertex) -> Vertex:
    i, b = v
    return g[i] if b == 0 else antipode(g[i])

def suspend(g: Map, n: int) -> Map:
    """Suspend an antipodal map S^m -> S^n to S^{m+1} -> S^{n+1}:
    keep g on the equator, send the new polar vertex to the new polar vertex."""
    return tuple(list(g) + [(n + 1, 0)])

def suspend_iter(g: Map, n: int, k: int) -> Map:
    """The k-fold suspension tower susp^k(g)."""
    cur, cn = g, n
    for _ in range(k):
        cur = suspend(cur, cn)
        cn += 1
    return cur

def compose(g2: Map, g1: Map) -> Map:
    return tuple(apply_map(g2, g1[i]) for i in range(len(g1)))

