import matplotlib.pyplot as plt
import numpy as np

def antipode(v):
    return (v[0], 1 - v[1])

def is_simplex(sigma) -> bool:
    seen = {}
    for (i, b) in sigma:
        if i in seen and seen[i] != b:
            return False
        seen[i] = b
    return True

def exists_map(m: int, n: int) -> bool:
    verts = [(i, b) for i in range(n + 1) for b in (0, 1)]
    facets = [tuple((i, s[i]) for i in range(m + 1)) for s in product((0, 1), repeat=m + 1)]
    for g in product(verts, repeat=m + 1):
        if all(is_simplex([g[i] if b == 0 else antipode(g[i]) for (i, b) in f]) for f in facets):
            return True
    return False

def main() -> None:
